const char *sts_bundled_query(const char *a_language, int a_kind)
	/* The query of `a_kind' (0 highlights, 1 folds, 2 brackets) for `a_language'; NULL when none. */
{
	if (strcmp(a_language, "eiffel") == 0) {
		if (a_kind == 0) {
			return q_eiffel_highlights;
		}
		if (a_kind == 1) {
			return q_eiffel_folds;
		}
		if (a_kind == 2) {
			return q_eiffel_brackets;
		}
	}
	if (strcmp(a_language, "c") == 0) {
		if (a_kind == 0) {
			return q_c_highlights;
		}
		if (a_kind == 1) {
			return q_c_folds;
		}
		if (a_kind == 2) {
			return q_c_brackets;
		}
	}
	if (strcmp(a_language, "json") == 0) {
		if (a_kind == 0) {
			return q_json_highlights;
		}
		if (a_kind == 1) {
			return q_json_folds;
		}
		if (a_kind == 2) {
			return q_json_brackets;
		}
	}
	if (strcmp(a_language, "xml") == 0) {
		if (a_kind == 0) {
			return q_xml_highlights;
		}
		if (a_kind == 1) {
			return q_xml_folds;
		}
		if (a_kind == 2) {
			return q_xml_brackets;
		}
	}
	return NULL;
}
